from pathlib import Path
import json
root=Path("card-lookup")
data={k:json.loads((root/"data"/f"{k}.json").read_text(encoding="utf-8")) for k in ("chrome25","pulse26","panini26","logo26")}
template=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Pack Room — All 4 Offline Card Lookup Tools</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#1b3044;font:16px/1.42 system-ui,-apple-system,Segoe UI,Arial,sans-serif}main{max-width:800px;margin:auto;padding:16px}header{padding:14px;background:#1a3550;color:white}header b{font-size:21px}header small{display:block;color:#deeffc}h1{font-size:27px;line-height:1.12;margin:5px 0 9px}h2{font-size:19px}p{margin:7px 0}.box{background:white;border:1px solid #dce6ed;border-radius:14px;padding:15px;margin-bottom:12px}label{display:block;font-weight:850;margin-bottom:6px}select,input{display:block;width:100%;font:inherit;font-size:18px;padding:13px;border:2px solid #91afc0;border-radius:10px;background:white;color:#102d40}input{font-size:21px;font-weight:740}.warn{padding:10px;background:#fff5e4;border-radius:10px;font-size:14px;color:#6f471a;margin:10px 0}.meta{font-size:13px;color:#566c7c}.result{border-left:5px solid #24709d;background:#f7fbff;border-radius:9px;margin:9px 0;padding:12px}.result strong{font-size:19px}.type{background:#def1fb;padding:3px 7px;border-radius:6px;display:inline-block;font-weight:750;font-size:12px;margin:5px 5px 5px 0}.hit{background:#d3f4df;color:#175632}.steps{display:grid;grid-template-columns:1fr 1fr;gap:9px}.step{padding:10px;border:1px solid #dce7ee;border-radius:10px;font-size:14px}.step b{display:block;color:#155a83}.button{border:1px solid #a6c5d9;background:#e8f5fc;color:#164869;font-size:14px;padding:9px 10px;border-radius:8px;margin:4px;cursor:pointer}a{color:#126590;font-weight:760}#matches:empty{display:none}@media(max-width:600px){.steps{grid-template-columns:1fr}h1{font-size:25px}}@media print{header,#set,#q,.button{display:none}.box{border:none}.steps{grid-template-columns:1fr 1fr}}
</style></head><body><header><b>⚾ PACK ROOM</b><small>All 4 exact products · Fully offline backup</small></header><main><div class="box"><label for="set">WHICH PRODUCT ARE YOU OPENING?</label><select id="set"><option value="chrome25">2025 Topps Chrome Update — Mega</option><option value="pulse26">2026 Pulse Big League Chew — Blaster</option><option value="panini26">2026 Panini USA Stars &amp; Stripes Prizm — Mega</option><option value="logo26">2026 Topps Chrome LogoFractor — Pack</option></select><h1 id="product"></h1><p class="meta" id="facts"></p><p id="boxclaim"></p></div><div class="box"><label for="q">🔎 CARD NUMBER OR PLAYER</label><input id="q" type="search" autocomplete="off" placeholder="Enter printed code or player name"><p class="meta" id="count"></p><div id="matches"></div><div class="warn">Number or player alone cannot prove a refractor, autograph, image variation, or rarity. Check the physical card and any serial number.</div></div><div class="box"><h2>⚡ WHAT TO LOOK FOR</h2><div id="tips" class="steps"></div><p class="warn" id="special"></p><button class="button" onclick="window.print()">🖨 Print this guide</button><a href="https://damienreilley.github.io/fantasy-baseball-2026/card-lookup/">Live website (when online)</a></div><p class="meta">All lookup entries embedded in this file. No internet, ChatGPT, account or server needed. Source data reflects publicly available published checklists.</p></main><script>
const DB=__EMBED_DATA__;
const DETAILS={chrome25:{title:"2025 Topps Chrome Update — Mega Box",facts:"7 packs × 6 cards · 200 base cards · 10 exclusive X-Fractors/box",claim:"Look for X-shaped X-Fractor shine, RC logos, autographs and numbered parallels.",tips:["X-Fractor: repeating X pattern","Numbered? check the /xx stamp","Autograph? look for real signature","RC logo? rookie card"],special:"USC45 may be Tommy Pham OR Cal Raleigh. USC80 may be Tyler Locklear OR Dustin May. There are no printed USC1 or USC167."},pulse26:{title:"2026 Pulse × Big League Chew — Blaster Box",facts:"6 packs × 8 cards · 48 cards/box · 6 numbered cards/box",claim:"Numbered parallels are the key feature. Autographs are random, not guaranteed.",tips:["Six numbered cards per box","Look for Big League Chew Signatures","Flavor inserts and cartoon Game Face cards","Special Chew Crew character cards"],special:"Physical color/serial number distinguishes parallels. A checklist match by code alone doesn't."},panini26:{title:"2026 Panini USA Stars & Stripes Prizm — Mega Box",facts:"10 packs × 4 cards · 40 cards/box · ~3 autographs or memorabilia on average",claim:"Check for actual ink, embedded materials and exclusive Ice Prizms.",tips:["Autographs: check for actual signature","Relics: an inserted material patch","Mega-exclusive Ice patterns","Ultra-rare Color Blast"],special:"Panini repeats numeric card codes across subsets. Confirm set design, not just the number. Mega configurations differ from Hobby/H2."},logo26:{title:"2026 Topps Chrome LogoFractor — Single Pack",facts:"5 cards in your purchased pack · 300-card LogoFractor base set",claim:"Look for repeating MLB logos, serial numbers, alternate photos and autographs.",tips:["MLB repeating logo pattern = LogoFractor","Pink /250 · Blue /150 · Green /99","Purple /75 · Gold /50 · Orange /25","Black /10 · Red /5 · Rose Gold 1/1"],special:"A loose five-card pack has no guaranteed autograph or numbered hit."}};
const el=id=>document.getElementById(id),esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])),norm=s=>String(s??"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim();
function render(){let k=el("set").value,d=DETAILS[k],data=DB[k].cards,term=norm(el("q").value).replace(/^#/,"");el("product").textContent=d.title;el("facts").textContent=d.facts;el("boxclaim").textContent=d.claim;el("tips").innerHTML=d.tips.map(t=>'<div class="step"><b>✓</b>'+esc(t)+'</div>').join("");el("special").textContent=d.special;
 if(!term){el("matches").innerHTML="";el("count").textContent=DB[k].count.toLocaleString()+" indexed checklist entries • Ready to search";return}
 let exact=data.filter(c=>norm(c.code).replace(/^#/,"")===term),matches=exact.length?exact:data.filter(c=>norm(c.name).includes(term)||norm(c.code).includes(term)||norm(c.set).includes(term));el("count").textContent=matches.length+" possible matches"+(matches.length>25?" (first 25 shown)":"");el("matches").innerHTML=matches.slice(0,25).map(c=>'<div class="result"><strong>'+esc(c.name)+'</strong> <span class="meta">#'+esc(c.code)+'</span><br><span class="type '+(/autograph|relic|variation/i.test(c.type)?'hit':'')+'">'+esc(c.type)+'</span><br><span class="meta">'+esc(c.set)+(c.team?" · "+esc(c.team):"")+'</span></div>').join("")||'<div class="warn">No checklist match. Double-check the product and printed code; this does not establish card value.</div>';
}
el("set").addEventListener("change",render);el("q").addEventListener("input",render);const params=new URLSearchParams(location.search);if(DETAILS[params.get("set")])el("set").value=params.get("set");render();
</script></body></html>'''
out=template.replace('__EMBED_DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</script>','<\\/script>'))
(root/'Pack_Room_Offline_All_Four.html').write_text(out,encoding='utf-8')
print('OFFLINE backup generated',len(out),'chars', {k:len(v['cards']) for k,v in data.items()})
